import { Component, signal, computed } from '@angular/core';

type Item = { name: string; price: number };

@Component({
  selector: 'app-cart',
  template: `
    <p>{{ items().length }} items, total {{ total() }}</p>
    <button (click)="add()">Add</button>
    <button (click)="discount.set(0.1)">10% off</button>
  `,
})
export class Cart {
  protected items = signal<Item[]>([{ name: 'Pen', price: 2 }]);
  protected discount = signal(0);
  protected total = computed(() => {
    const sum = this.items().reduce((s, i) => s + i.price, 0);
    return Math.round(sum * (1 - this.discount()) * 100) / 100;
  });

  protected add() {
    // this.items().push(...) would NOT update the view
    this.items.update((list) => [...list, { name: 'Pad', price: 5 }]);
  }
}

