import { Component, signal, computed } from '@angular/core';

type Todo = { id: number; title: string; done: boolean };

@Component({
  selector: 'app-todos',
  template: `
    @switch (filter()) {
      @case ('open') { <h2>Open tasks</h2> }
      @default { <h2>All tasks</h2> }
    }
    @for (t of visible(); track t.id; let i = $index) {
      <p [class.done]="t.done">{{ i + 1 }}. {{ t.title }}</p>
    } @empty { <p>Nothing to do</p> }
    @if (visible().length > 2) { <p>Busy day!</p> } @else { <p>Light day</p> }
  `,
})
export class Todos {
  protected filter = signal<'all' | 'open'>('open');
  protected todos = signal<Todo[]>([
    { id: 1, title: 'Learn @for', done: true }, { id: 2, title: 'Use track', done: false },
  ]);
  protected visible = computed(() =>
    this.filter() === 'all' ? this.todos() : this.todos().filter((t) => !t.done));
}

