import { Component, signal, computed, effect, linkedSignal, untracked } from '@angular/core';
@Component({
  selector: 'app-shipping',
  template: `
    <select (change)="country.set($any($event.target).value)">
      <option>NL</option><option>US</option>
    </select>
    @for (m of methods(); track m) {
      <label><input type="radio" [checked]="m === method()" (change)="method.set(m)" /> {{ m }}</label>
    }`,
})
export class Shipping {
  protected country = signal('NL');
  protected methods = computed(() => (this.country() === 'US' ? ['UPS', 'FedEx'] : ['PostNL', 'DHL']));
  // resets to the first method when methods() changes, but stays user-writable
  protected method = linkedSignal(() => this.methods()[0]);
  private userId = signal(42);
  constructor() {
    effect(() => {
      const m = this.method();                 // dependency
      console.log('save', untracked(this.userId), m);   // userId is not a dependency
      localStorage.setItem('shipping', m);
    });
  }
}

