import { Component, DestroyRef, ElementRef, OnInit, afterNextRender, afterRenderEffect,
         inject, input, signal, viewChild } from '@angular/core';

@Component({
  selector: 'app-clock-chart',
  template: `<p>{{ title() }}: {{ now() }}</p><canvas #c width="200" height="20"></canvas>`,
})
export class ClockChart implements OnInit {
  title = input('Clock');
  protected now = signal(new Date());
  private canvas = viewChild.required<ElementRef<HTMLCanvasElement>>('c');

  constructor() {
    const id = setInterval(() => this.now.set(new Date()), 1000);
    inject(DestroyRef).onDestroy(() => clearInterval(id));       // cleanup

    afterNextRender(() => console.log('first paint, browser only'));
    afterRenderEffect(() => {                                    // re-runs when now() changes
      const ctx = this.canvas().nativeElement.getContext('2d')!;
      ctx.clearRect(0, 0, 200, 20);
      ctx.fillRect(0, 0, this.now().getSeconds() * 3, 20);
    });
  }
  ngOnInit() { console.log('inputs ready:', this.title()); }
}

