import { inject } from '@angular/core';
import { CanActivateFn, CanDeactivateFn, ResolveFn, Router, Routes } from '@angular/router';
import { HttpClient } from '@angular/common/http';

declare class Auth { isLoggedIn(): boolean; hasRole(r: string): boolean }   // your service
type Project = { id: string; name: string };

export const authGuard: CanActivateFn = (route, state) =>
  inject(Auth).isLoggedIn() ||
  inject(Router).createUrlTree(['/login'], { queryParams: { next: state.url } });
export const roleGuard = (role: string): CanActivateFn => () => inject(Auth).hasRole(role);
export const unsavedGuard: CanDeactivateFn<{ dirty(): boolean }> = (cmp) =>
  !cmp.dirty() || confirm('Discard unsaved changes?');
export const projectResolver: ResolveFn<Project> = (route) =>
  inject(HttpClient).get<Project>(`/api/projects/${route.paramMap.get('id')}`);

export const routes: Routes = [
  { path: 'projects/:id', canActivate: [authGuard], canDeactivate: [unsavedGuard],
    resolve: { project: projectResolver },             // -> project input
    loadComponent: () => import('./project').then((m) => m.ProjectPage) },
  { path: 'admin', canMatch: [roleGuard('admin')],
    loadChildren: () => import('./admin/routes').then((m) => m.adminRoutes) },
];

concepts.body:
**`@defer`** lazy-loads a section of a template. The build moves the components, directives and pipes used only inside the block into a separate file (a **chunk**), which is downloaded and shown when a **trigger** fires.

```html
@defer (on viewport) { <app-comments /> }
@placeholder { <p>Comments</p> }
@loading (minimum 300ms) { <app-spinner /> }
@error { <p>Could not load comments</p> }
```

Triggers:

- `on idle` (the default) — when the browser is idle.
- `on viewport` — when the placeholder (or a referenced element) scrolls into view.
- `on interaction` / `on hover` — when the user clicks/focuses or hovers the placeholder or a referenced element (`on interaction(trigger)` with `#trigger`).
- `on immediate`, `on timer(2s)`, and `when condition()` for custom logic.

Add **prefetching** to download early but render later: `@defer (on interaction; prefetch on idle)`.

Sub-blocks: `@placeholder` shows before the trigger (with `minimum` to avoid flicker), `@loading` while the chunk loads (`after` and `minimum` parameters), `@error` if loading fails.

Rules: the components, directives and pipes inside the block must be standalone and not referenced elsewhere in the same file; otherwise they go into the main bundle and load up front. Triggers that need the DOM (`viewport`, `interaction`, `hover`) require a single root element in `@placeholder` or a reference.

When the page is built on the server (server-side rendering), `@defer` renders the placeholder; with incremental hydration it can render the real content there instead (see the SSR lesson).

concepts.code:
import { Component, signal } from '@angular/core';
import { Comments } from './comments';      // standalone, used only inside @defer
import { HeavyChart } from './heavy-chart';

@Component({
  selector: 'app-article',
  imports: [Comments, HeavyChart],
  template: `
    <article>...long text...</article>
    @defer (on viewport; prefetch on idle) {
      <app-comments />
    } @placeholder (minimum 200ms) {
      <p>Comments load when you scroll here</p>
    } @loading (after 100ms; minimum 300ms) {
      <p>Loading comments...</p>
    } @error {
      <p>Comments are unavailable</p>
    }
    <button #show>Show stats</button>
    @defer (on interaction(show)) { <app-heavy-chart /> }
    @defer (when isAdmin()) { <p>Admin tools loaded</p> }`,
})
export class Article {
  protected isAdmin = signal(false);
}

import { TestBed } from '@angular/core/testing';
import { provideHttpClient } from '@angular/common/http';
import { HttpTestingController, provideHttpClientTesting } from '@angular/common/http/testing';
import { UserDetail } from './user-detail';          // the httpResource example component

describe('UserDetail', () => {
  beforeEach(() => {
    TestBed.configureTestingModule({ providers: [provideHttpClient(), provideHttpClientTesting()] });
  });

  it('renders the loaded user', async () => {
    const fixture = TestBed.createComponent(UserDetail);
    const http = TestBed.inject(HttpTestingController);
    await fixture.whenStable();

    http.expectOne('https://jsonplaceholder.typicode.com/users/1')
        .flush({ id: 1, name: 'Ada', email: 'ada@example.com' });
    await fixture.whenStable();

    const el: HTMLElement = fixture.nativeElement;
    expect(el.querySelector('h2')?.textContent).toContain('Ada');
    http.verify();                                   // no unexpected requests
  });
});

import { ChangeDetectionStrategy, ChangeDetectorRef, Component, inject, signal } from '@angular/core';

@Component({
  selector: 'app-status',                        // OnPush by default in v22
  template: `<p>Signal: {{ status() }}</p> <p>Plain field: {{ plain }}</p>`,
})
export class Status {
  protected status = signal('waiting');
  protected plain = 'waiting';
  private cdr = inject(ChangeDetectorRef);
  constructor() {
    setTimeout(() => this.status.set('done'), 1000);   // signal notifies Angular -> re-render
    setTimeout(() => (this.plain = 'stale?'), 2000);   // nothing notifies: view keeps old text
    setTimeout(() => {
      this.plain = 'really done';
      this.cdr.markForCheck();                         // manual notification for plain state
    }, 3000);
  }
}
@Component({
  selector: 'app-legacy',
  changeDetection: ChangeDetectionStrategy.Eager,      // opt out of OnPush
  template: `{{ counter }}`,
})
export class Legacy { counter = 0; }

import { Component, Injectable, InjectionToken, inject, signal } from '@angular/core';

export interface AppConfig { apiUrl: string; retries: number }
export const APP_CONFIG = new InjectionToken<AppConfig>('APP_CONFIG', {
  providedIn: 'root',
  factory: () => ({ apiUrl: '/api', retries: 2 }),       // default, tree-shakable
});

@Injectable()                                             // not auto-provided
export class Counter { value = signal(0); }

@Component({
  selector: 'app-counter-panel',
  providers: [Counter],                                    // new instance per panel
  template: `<button (click)="c.value.set(c.value() + 1)">{{ c.value() }}</button>`,
})
export class CounterPanel { protected c = inject(Counter); }

@Component({ selector: 'app-tree-node', template: `depth {{ depth }}<ng-content />` })
export class TreeNode {
  private parent = inject(TreeNode, { optional: true, skipSelf: true });  // nearest ancestor
  protected depth: number = this.parent ? this.parent.depth + 1 : 0;
}
