// theme.ts - browser APIs used safely
import { Component, afterNextRender, signal } from '@angular/core';
@Component({
  selector: 'app-theme',
  template: `<p>Theme: {{ theme() }}</p>
             @defer (hydrate on viewport) { <p>Hydrated lazily</p> }`,
})
export class Theme {
  protected theme = signal('light');           // same on server and first client render
  constructor() {
    afterNextRender(() => this.theme.set(localStorage.getItem('theme') ?? 'light'));
  }
}
